let stocks = await d3.json('data/stock-descriptions.json');
  stocks = stocks.map(s => ({
    ...s,
    isETF: s.sector === 'ETF' || s.ticker.startsWith('SPY') || s.ticker.startsWith('QQQ') || s.ticker.startsWith('IWM') || s.ticker.startsWith('DIA'),
    name: s.name || s.ticker,
    marketCap: s.marketCap && !isNaN(+s.marketCap) ? +s.marketCap : null
  }));

